// Content script job extraction
const extractJobData = () => {
    const selectors = getSelectorsForSite(window.location.hostname);

    return {
        title: document.querySelector(selectors.title)?.textContent,
        company: document.querySelector(selectors.company)?.textContent,
        location: document.querySelector(selectors.location)?.textContent,
        description: document.querySelector(selectors.description)?.innerHTML,
        url: window.location.href,
        savedAt: new Date().toISOString()
    };
};

// Template variable replacement
const applyTemplate = (template, variables) => {
    return template.replace(/{{(\w+)}}/g, (match, key) => {
        return variables[key] || match;
    });
};
